new="""dc5,dc4=direct_core(X,pairc);score=(stat-ss[500].mean())/(ss[500].std()+1e-9)+.20*(dc5-c5.mean())/(c5.std()+1e-9)+.15*(dc4-c4.mean())/(c4.std()+1e-9)\n # Weak frequency layer. Existing structural filters/quotas and Committee remain primary.\n # Previous main numbers receive NO frequency bonus, so a hot previous number (e.g. 35) is not pushed again by this layer.\n prev_arr=set(map(int,draws[-1]))\n num_freq=np.zeros(44,float)\n digit_freq=np.zeros(10,float)\n digit_card=np.array([4,5,5,5,4,4,4,4,4,4],float)\n for ww in (20,50,100):\n  cnt=np.bincount(draws[-ww:].ravel(),minlength=44).astype(float)\n  zz=(cnt[1:44]-cnt[1:44].mean())/(cnt[1:44].std()+1e-9)\n  num_freq[1:44]+=zz/3.0\n  dc=np.zeros(10,float)\n  for d in range(10):dc[d]=sum(cnt[n] for n in range(1,44) if n%10==d)\n  expected=6.0*ww*digit_card/43.0\n  ratio=dc/expected\n  zr=(ratio-ratio.mean())/(ratio.std()+1e-9)\n  digit_freq+=zr/3.0\n for n in prev_arr:num_freq[n]=0.0\n cand_num=np.zeros(len(X),float);cand_digit=np.zeros(len(X),float)\n for ii,row in enumerate(X):\n  vals=[int(x) for x in row if int(x) not in prev_arr]\n  if vals:\n   cand_num[ii]=np.mean([num_freq[x] for x in vals])\n   cand_digit[ii]=np.mean([digit_freq[x%10] for x in vals])\n zn=(cand_num-cand_num.mean())/(cand_num.std()+1e-9)\n zd=(cand_digit-cand_digit.mean())/(cand_digit.std()+1e-9)\n frequency_adjust=0.10*zn+0.05*zd\n prev_overlap_pref=0.03*(po==0).astype(float)\n final_score=score+frequency_adjust+prev_overlap_pref\n order=np.argsort(final_score)[::-1]\n\n def choose_freqsoft(order,combs,meta,prev_set,n=10):\n  sum_quota={'L105-115':1,'M116-135':2,'C136-155':4,'H156-175':2,'X>=176':1}\n  layer_quota={'A':3,'B':3,'C':2,'D':2}\n  usedbin=Counter();usedlayer=Counter();shape_count=Counter();num_count=Counter();pair_count=Counter();triple_count=Counter();prevnum_count=Counter();sel=[];prev_ticket_count=0\n  def acceptable(i,strict=True):\n   row=tuple(combs[int(i)]);sb=sum_bin(sum(row));m=meta[int(i)];sh=m['shape'];ly=m['layer'];ov=[x for x in row if x in prev_set]\n   if sb=='OUT' or usedbin[sb]>=sum_quota[sb] or usedlayer[ly]>=layer_quota[ly] or shape_count[sh]>=2:return False\n   if ov and prev_ticket_count>=5:return False\n   if any(prevnum_count[x]>=2 for x in ov):return False\n   if strict:\n    pairs=list(itertools.combinations(row,2));triples=list(itertools.combinations(row,3))\n    if any(pair_count[x]>=2 for x in pairs) or any(triple_count[x]>=1 for x in triples) or any(num_count[x]>=4 for x in row):return False\n   return True\n  def add(i):\n   nonlocal prev_ticket_count\n   row=tuple(combs[int(i)]);sb=sum_bin(sum(row));m=meta[int(i)];sh=m['shape'];ly=m['layer'];ov=[x for x in row if x in prev_set]\n   sel.append(int(i));usedbin[sb]+=1;usedlayer[ly]+=1;shape_count[sh]+=1\n   if ov:prev_ticket_count+=1\n   for x in ov:prevnum_count[x]+=1\n   for x in row:num_count[x]+=1\n   for x in itertools.combinations(row,2):pair_count[x]+=1\n   for x in itertools.combinations(row,3):triple_count[x]+=1\n  for strict in (True,False):\n   for i in order:\n    if int(i) in sel:continue\n    if acceptable(i,strict):add(i)\n    if len(sel)==n:break\n   if len(sel)==n:break\n  return sel,sum_quota,layer_quota,prev_ticket_count,prevnum_count\n\n sel,sum_quota,layer_quota,prev_ticket_count,prevnum_count=choose_freqsoft(order,combs,meta,prev_arr,10)"""
